    }
  },

  moveDropdownBack() {
    if (this.isPortalActive && this.dropdown && this.originalParent) {
      this.originalParent.appendChild(this.dropdown);
      this.isPortalActive = false;
      if (this.portalContainer) {
        this.portalContainer.style.pointerEvents = "none";
      }

