        computedStyle.overflow === "hidden" ||
        computedStyle.overflowX === "hidden" ||
        computedStyle.overflowY === "hidden"
      ) {
        return true;
      }
      element = element.parentElement;
    }
    return false;
  },

  handleOpenButtonClick(e) {
    e.preventDefault();
    e.stopPropagation();
    if (this.dropdown.hasAttribute("hidden")) {
      this.openDropdown();
    } else {
      this.closeDropdown();
    }
  },

  openDropdown() {
