  handleKeyDown(e) {
    const key = e.key;

    if (
      this.dropdown.hasAttribute("hidden") &&
      document.activeElement === this.openButton
    ) {
      if (key === " " || key === "Enter") {
        e.preventDefault();
        this.openDropdown();
        return;
      }
      return;
    }

    if (this.dropdown.hasAttribute("hidden")) return;

    if (key === "Escape") {
      this.closeDropdown();
      this.openButton.focus();
      return;
    }

    const isNavigationKey = [
      "ArrowDown",
      "ArrowUp",
      "Enter",
      "Tab",
      "Escape",
    ].includes(key);

    if (
      this.searchInput &&
      document.activeElement === this.searchInput &&
      !isNavigationKey &&
      key.length === 1
    ) {
      return;
    }

    const visibleOptions = Array.from(this.getDropdownOptions()).filter(
      (opt) => opt.style.display !== "none",
    );

    if (this.creatable && this.createOption && !this.createOption.hidden) {
      visibleOptions.push(this.createOption);
    }

    if (visibleOptions.length === 0) return;

    let currentIndex = visibleOptions.findIndex((opt) =>
      opt.hasAttribute("data-combobox-navigate"),
    );

    if (key === "ArrowDown") {
      e.preventDefault();
      e.stopPropagation();
      currentIndex =
        currentIndex < 0 ? 0 : (currentIndex + 1) % visibleOptions.length;
      this.navigateToOption(visibleOptions[currentIndex]);
      return;
    } else if (key === "ArrowUp") {
      e.preventDefault();
      e.stopPropagation();
      currentIndex =
        currentIndex < 0
          ? visibleOptions.length - 1
          : (currentIndex - 1 + visibleOptions.length) % visibleOptions.length;
      this.navigateToOption(visibleOptions[currentIndex]);
      return;
    } else if (key === "Enter") {
      e.preventDefault();
      e.stopPropagation();
      if (currentIndex >= 0) {
        const targetOption = visibleOptions[currentIndex];

        if (this.creatable && targetOption === this.createOption) {
          this.createNewOption(this.searchInput ? this.searchInput.value : "");
          return;
        }

        const value = targetOption.dataset.comboboxValue;
        this.lastNavigatedValue = value;

        if (this.select.multiple) {
          this.toggleOption(value, targetOption);
          this.updateMultipleSelectedDisplay();
          this.dispatchChangeEvent();
          this.navigateToOption(targetOption);
        } else {
          Array.from(this.getDropdownOptions()).forEach((opt) => {
            opt.removeAttribute("data-combobox-selected");
            opt.setAttribute("aria-selected", "false");
          });
          this.selectSingleOption(value);
          targetOption.setAttribute("data-combobox-selected", "");
          targetOption.setAttribute("aria-selected", "true");
          this.closeDropdown();
          this.openButton.focus();
        }
      }
      return;
    } else if (key === "Tab") {
      this.closeDropdown();
      return;
    } else if (key.length === 1) {
      e.preventDefault();
      this.handleCharacterNavigation(key.toLowerCase(), visibleOptions);
      return;
    } else {
      return;
    }
  },

  handleCharacterNavigation(char, options) {
    const matchingOptions = options.filter((opt) => {
      const valueAttr = opt.getAttribute("data-combobox-value") || "";
      const labelText = opt.textContent.trim().toLowerCase();
      return (
        valueAttr.toLowerCase().startsWith(char) || labelText.startsWith(char)
      );
    });
    if (matchingOptions.length === 0) return;

    let currentIndex = matchingOptions.findIndex((opt) =>
      opt.hasAttribute("data-combobox-navigate"),
    );
    currentIndex = (currentIndex + 1) % matchingOptions.length;

    this.navigateToOption(matchingOptions[currentIndex]);
  },

  handleCreateOptionClick(e) {
    e.preventDefault();
    e.stopPropagation();
    if (this.searchInput) {
      this.createNewOption(this.searchInput.value);
    }
  },

  buildOptionElement(value, label) {
    const el = document.createElement("div");
    el.setAttribute("role", "option");
    el.classList.add(
      "combobox-option",
      "cursor-pointer",
      "rounded",
      "flex",
      "justify-between",
      "items-center",
    );
    el.setAttribute("data-combobox-value", value);

    const span = document.createElement("span");
    span.textContent = label || value;
    el.appendChild(span);

    const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute(
      "class",
      "hidden [[data-combobox-selected]_&]:block shrink-0 w-3.5 h-3.5 combobox-icon",
    );
    svg.setAttribute("fill", "none");
    svg.setAttribute("viewBox", "0 0 24 24");
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    Object.entries({
      stroke: "currentColor",
      "stroke-linecap": "round",
      "stroke-linejoin": "round",
      "stroke-width": "2",
      d: "M20 6 9 17l-5-5",
    }).forEach(([k, v]) => path.setAttribute(k, v));
    svg.appendChild(path);
    el.appendChild(svg);

    return el;
  },

  selectCreatedOption(selectOpt, optionEl) {
    if (this.select.multiple) {
      selectOpt.selected = true;
      selectOpt.setAttribute("selected", "");
      optionEl.setAttribute("data-combobox-selected", "");
      optionEl.setAttribute("aria-selected", "true");
      this.updateMultipleSelectedDisplay();
    } else {
      Array.from(this.select.options).forEach((o) => (o.selected = false));
      Array.from(this.getDropdownOptions()).forEach((o) => {
        o.removeAttribute("data-combobox-selected");
        o.setAttribute("aria-selected", "false");
      });
      selectOpt.selected = true;
      optionEl.setAttribute("data-combobox-selected", "");
      optionEl.setAttribute("aria-selected", "true");
      this.updateSingleSelectedDisplay();
      this.closeDropdown();
      this.openButton.focus();
    }
  },

  refreshSelectedDisplay() {
    if (this.select.multiple) {
      this.updateMultipleSelectedDisplay();
    } else {
      this.updateSingleSelectedDisplay();
    }
  },

  handleCreateReply(reply, selectOpt, optionEl) {
    if (reply.error) {
      this.removeCreatedOption(selectOpt, optionEl, reply.error);
      return;
    }

    if (reply.value) {
      selectOpt.value = reply.value;
      optionEl.setAttribute("data-combobox-value", reply.value);
    }

    if (reply.label) {
      selectOpt.textContent = reply.label;
      optionEl.querySelector("span").textContent = reply.label;
    }

    if (reply.value || reply.label) {
      this.refreshSelectedDisplay();
    }
  },

  removeCreatedOption(selectOpt, optionEl, errorMsg) {
    selectOpt.remove();
    optionEl.remove();
    this.setupOptionListeners();
    this.refreshSelectedDisplay();
    this.dispatchChangeEvent();

    if (errorMsg) {
      const errEl = document.createElement("div");
      errEl.textContent = errorMsg;
      errEl.classList.add(
        "combobox-create-error",
        "text-center",
        "text-red-500",
        "py-2",
        "text-sm",
      );
      errEl.addEventListener("click", (e) => {
        e.preventDefault();
        e.stopPropagation();
      });

      const searchWrapper = this.dropdown
        .querySelector(".combobox-search-input")
        ?.closest("div");
      if (searchWrapper) {
        searchWrapper.after(errEl);
      } else {
        this.dropdown.prepend(errEl);
      }

      this.openDropdown();
    }
  },

  clearSearchState() {
    if (this.searchInput) {
      this.searchInput.value = "";
      Array.from(this.getDropdownOptions()).forEach(
        (o) => (o.style.display = ""),
      );
    }
    if (this.createOption) this.createOption.hidden = true;
    const noResults = this.dropdown.querySelector(".no-results");
    if (noResults) noResults.classList.add("hidden");
  },

  createNewOption(value) {
    const trimmed = (value || "").trim();
    if (!trimmed) return;

    const isDuplicate = Array.from(this.select.options).some(
      (opt) => opt.value.toLowerCase() === trimmed.toLowerCase(),
    );
    if (isDuplicate) return;

    const selectOpt = document.createElement("option");
    selectOpt.value = trimmed;
    selectOpt.textContent = trimmed;
    this.select.appendChild(selectOpt);

    const optionEl = this.buildOptionElement(trimmed);
    const anchor =
      this.createOption || this.dropdown.querySelector(".no-results");
    if (anchor?.parentNode) anchor.parentNode.insertBefore(optionEl, anchor);

    this.setupOptionListeners();
    this.selectCreatedOption(selectOpt, optionEl);
    this.clearSearchState();
    this.dispatchChangeEvent();
    this.lastNavigatedValue = trimmed;

    if (this.onCreateEvent) {
      this.pushEventTo(this.el, 
        this.onCreateEvent,
        { id: this.el.id.replace(/-combo$/, ""), value: trimmed },
        (reply) => this.handleCreateReply(reply, selectOpt, optionEl),
      );
    }
  },

  syncDisplayFromSelect() {
    Array.from(this.getDropdownOptions()).forEach((opt) => {
      opt.removeAttribute("data-combobox-selected");
      opt.setAttribute("aria-selected", "false");
    });

    if (this.select.multiple) {
      this.updateMultipleSelectedDisplay();
    } else {
      this.updateSingleSelectedDisplay();
    }
  },

  handleDocumentClick(e) {
    if (
      !this.el.contains(e.target) &&
      !(
        this.isPortalActive &&
        this.portalContainer &&
        this.portalContainer.contains(e.target)
      ) &&
      !this.isClickOnScrollbar(e)
    ) {
      this.closeDropdown();
    }
  },

  isClickOnScrollbar(e) {
    return (
      e.clientX >= document.documentElement.clientWidth ||
      e.clientY >= document.documentElement.clientHeight
    );
  },

  dispatchChangeEvent() {
    const changeEvent = new Event("change", { bubbles: true });
    this.select.dispatchEvent(changeEvent);
  },

  handleClearButtonClick(e) {
    e.preventDefault();
    e.stopPropagation();
    Array.from(this.select.options).forEach((opt) => {
      opt.selected = false;
      opt.removeAttribute("selected");
    });
    Array.from(this.getDropdownOptions()).forEach((opt) => {
      opt.removeAttribute("data-combobox-selected");
      opt.setAttribute("aria-selected", "false");
    });
    this.syncDisplayFromSelect();
    this.closeDropdown();
    this.dispatchChangeEvent();
    this.resetNavigateToFirstOption();
  },

  destroyed() {
    this.closeDropdown();

    if (this.portalContainer && this.portalContainer.parentNode) {
      this.portalContainer.parentNode.removeChild(this.portalContainer);
    }

    if (this.observer) {
      this.observer.disconnect();
    }

    document.removeEventListener("click", this.boundHandleDocumentClick, true);
    if (this.openButton && this.boundOpenButtonClick) {
      this.openButton.removeEventListener("click", this.boundOpenButtonClick);
      this.openButton.removeEventListener("keydown", this.boundHandleKeyDown);
    }

    if (
      this.boundOptionClickHandlers &&
      this.boundOptionClickHandlers.length > 0
    ) {
      this.boundOptionClickHandlers.forEach(({ btn, handler }) => {
        btn.removeEventListener("click", handler);
      });
    }

    if (this.searchInput && this.boundSearchInputHandler) {
      this.searchInput.removeEventListener(
        "input",
        this.boundSearchInputHandler,
      );
      this.searchInput.removeEventListener(
        "change",
        this.boundSearchChangeHandler,
      );
      this.searchInput.removeEventListener("keydown", this.boundHandleKeyDown);
    }

    if (this.clearButton && this.boundClearButtonClick) {
      this.clearButton.removeEventListener("click", this.boundClearButtonClick);
    }

    if (this.createOption && this.boundCreateOptionClick) {
      this.createOption.removeEventListener(
        "click",
        this.boundCreateOptionClick,
      );
    }
  },
};

export default Combobox;

const Carousel = {
  mounted() {
    try {
      this.initializeElements();
      this.setupState();
      this.setupEventListeners();
      this.setupImageLoadHandling();
      this.setupKeyboardNavigation();
      this.setupTouchNavigation();
      this.setupResizeHandling();
      this.showInitialSlide();
      this.setupAutoplay();
      this.setupIntersectionObserver();

      this.handleEvent("select-slide", ({ index }) => this.selectSlide(index));
    } catch (error) {
      console.error(`Carousel initialization error: ${error.message}`);
    }
  },

  disconnected() {
    this.cleanupEventListeners();
    this.stopAutoplay();
    if (this.intersectionObserver) {
      this.intersectionObserver.disconnect();
    }
  },

  initializeElements() {
    this.slides = this.el.querySelectorAll(".slide");
    if (!this.slides.length) {
      throw new Error("No slides found in carousel");
    }

    this.indicators = this.el.querySelectorAll(".carousel-indicator");
    this.prevButtons = [
      this.el.querySelector(`#${this.el.id}-carousel-prev`),
    ].filter(Boolean);
    this.nextButtons = [
      this.el.querySelector(`#${this.el.id}-carousel-next`),
    ].filter(Boolean);
    this.imageLoaders = this.el.querySelectorAll(
      `[id^="${this.el.id}-carousel-slide-image-"]`,
    );

    this.prevButtons.forEach((button) => {
      if (!button.getAttribute("aria-label")) {
        button.setAttribute("aria-label", "Previous slide");
      }
    });

    this.nextButtons.forEach((button) => {
      if (!button.getAttribute("aria-label")) {
        button.setAttribute("aria-label", "Next slide");
      }
    });

    if (!this.el.getAttribute("role")) {
      this.el.setAttribute("role", "region");
      this.el.setAttribute("aria-roledescription", "carousel");
    }

    // Set sanitized ARIA attributes for each slide
    this.slides.forEach((slide, index) => {
      slide.setAttribute("role", "group");
      slide.setAttribute("aria-roledescription", "slide");
      slide.setAttribute(
        "aria-label",
        `Slide ${this.sanitizeNumber(index) + 1} of ${this.sanitizeNumber(this.slides.length)}`,
      );
    });
  },

  setupState() {
    // Validate active index strictly
    const rawIndex = this.el.dataset.activeIndex;
    this.activeIndex = /^\d+$/.test(rawIndex)
      ? Math.max(1, Math.min(parseInt(rawIndex, 10), this.slides.length))
      : 1;

    this.totalSlides = this.slides.length;

    // Validate class names to prevent injection
    this.classes = {
      activeSlide:
        this.sanitizeClassName(this.el.dataset.activeSlideClass) ||
        "active-slide z-10",
      hiddenSlide:
        this.sanitizeClassName(this.el.dataset.hiddenSlideClass) || "opacity-0",
      activeIndicator:
        this.sanitizeClassName(this.el.dataset.activeIndicatorClass) ||
        "active-indicator",
    };

    // Validate boolean values
    this.shouldAutoplay = this.el.dataset.autoplay === "true";

    // Validate numeric values and add a maximum for safety
    const rawInterval = parseInt(this.el.dataset.autoplayInterval, 10);
    this.autoplayInterval =
      !isNaN(rawInterval) && rawInterval > 0
        ? Math.min(rawInterval, 30000)
        : 5000;

    this.autoplayTimer = null;
    this.userInteractionDelay = 7000;
    this.userInteractionTimeout = null;
    this.isHovered = false;
    this.isTouching = false;
    this.touchStartX = 0;
    this.touchEndX = 0;
    this.minSwipeDistance = 50;
  },

  setupEventListeners() {
    this.eventHandlers = {
      prevClick: (e) => {
        this.handleUserInteraction();
        this.handlePrevClick(e);
      },
      nextClick: (e) => {
        this.handleUserInteraction();
        this.handleNextClick(e);
      },
      indicatorClick: (index) => {
        this.handleUserInteraction();
        this.handleIndicatorClick(index + 1);
      },
      mouseEnter: () => {
        this.isHovered = true;
        if (this.shouldAutoplay && this.el.dataset.pauseOnHover !== "false") {
          this.stopAutoplay();
        }
      },
      mouseLeave: () => {
        this.isHovered = false;
        if (
          this.shouldAutoplay &&
          !this.isTouching &&
          this.el.dataset.pauseOnHover !== "false"
        ) {
          this.startAutoplay();
        }
      },
      touchStart: (e) => {
        this.isTouching = true;
        this.touchStartX = e.touches[0].clientX;
        if (this.shouldAutoplay) {
          this.stopAutoplay();
        }
      },
      touchMove: (e) => {
        if (!this.isTouching) return;
        this.touchEndX = e.touches[0].clientX;
      },
      touchEnd: () => {
        this.isTouching = false;
        this.handleSwipe();
        if (this.shouldAutoplay && !this.isHovered) {
          this.startAutoplay();
        }
      },
      keyDown: (e) => this.handleKeyDown(e),
      resize: () => this.handleResize(),
    };

    this.prevButtons.forEach((button) => {
      button?.addEventListener("click", this.eventHandlers.prevClick);
    });

    this.nextButtons.forEach((button) => {
      button?.addEventListener("click", this.eventHandlers.nextClick);
    });

    this.indicators?.forEach((indicator, index) => {
      indicator.addEventListener("click", () =>
        this.eventHandlers.indicatorClick(index),
      );
    });

    if (this.el.dataset.pauseOnHover !== "false") {
      this.el.addEventListener("mouseenter", this.eventHandlers.mouseEnter);
      this.el.addEventListener("mouseleave", this.eventHandlers.mouseLeave);
    }
  },

  cleanupEventListeners() {
    this.prevButtons.forEach((button) => {
      button?.removeEventListener("click", this.eventHandlers.prevClick);
    });

    this.nextButtons.forEach((button) => {
      button?.removeEventListener("click", this.eventHandlers.nextClick);
    });

    this.indicators?.forEach((indicator, index) => {
      indicator.removeEventListener("click", () =>
        this.eventHandlers.indicatorClick(index),
      );
    });

    this.el.removeEventListener("mouseenter", this.eventHandlers.mouseEnter);
    this.el.removeEventListener("mouseleave", this.eventHandlers.mouseLeave);

    document.removeEventListener("keydown", this.eventHandlers.keyDown);
    window.removeEventListener("resize", this.eventHandlers.resize);

    this.el.removeEventListener("touchstart", this.eventHandlers.touchStart);
    this.el.removeEventListener("touchmove", this.eventHandlers.touchMove);
    this.el.removeEventListener("touchend", this.eventHandlers.touchEnd);
  },

  setupKeyboardNavigation() {
    document.addEventListener("keydown", this.eventHandlers.keyDown);
  },

  handleKeyDown(e) {
    const hasFocus =
      this.el.contains(document.activeElement) ||
      document.activeElement === this.el;

    if (!hasFocus) return;

    if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
      this.handleUserInteraction();
      this.handlePrevClick(e);
      e.preventDefault();
    } else if (e.key === "ArrowRight" || e.key === "ArrowDown") {
      this.handleUserInteraction();
      this.handleNextClick(e);
      e.preventDefault();
    }
  },

  setupTouchNavigation() {
    this.el.addEventListener("touchstart", this.eventHandlers.touchStart, {
      passive: true,
    });
    this.el.addEventListener("touchmove", this.eventHandlers.touchMove, {
      passive: true,
    });
    this.el.addEventListener("touchend", this.eventHandlers.touchEnd);
  },

  handleSwipe() {
    if (!this.touchStartX || !this.touchEndX) return;

    const swipeDistance = this.touchEndX - this.touchStartX;

    if (Math.abs(swipeDistance) > this.minSwipeDistance) {
      if (swipeDistance > 0) {
        this.handlePrevClick(new Event("swipe"));
      } else {
        this.handleNextClick(new Event("swipe"));
      }
    }

    this.touchStartX = 0;
    this.touchEndX = 0;
  },

  setupResizeHandling() {
    window.addEventListener("resize", this.eventHandlers.resize);
  },

  handleResize() {
    if (this.resizeTimeout) {
      clearTimeout(this.resizeTimeout);
    }

    this.resizeTimeout = setTimeout(() => {
      this.updateSlideSizes();
    }, 100);
  },

  updateSlideSizes() {
    const containerWidth = this.el.clientWidth;
    this.slides.forEach((slide) => {
      const img = slide.querySelector("img");
      if (img) {
        const aspectRatio = img.naturalHeight / img.naturalWidth;
        img.style.maxHeight = `${containerWidth * aspectRatio}px`;
      }
    });
  },

  setupIntersectionObserver() {
    if ("IntersectionObserver" in window && this.shouldAutoplay) {
      this.intersectionObserver = new IntersectionObserver(
        (entries) => {
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              if (this.shouldAutoplay && !this.isHovered && !this.isTouching) {
                this.startAutoplay();
              }
            } else {
              this.stopAutoplay();
            }
          });
        },
        { threshold: 0.2 },
      );
      this.intersectionObserver.observe(this.el);
    }
  },

  handlePrevClick(e) {
    const targetIndex =
      this.activeIndex > 1 ? this.activeIndex - 1 : this.totalSlides;
    this.navigateToSlide(targetIndex);
    e.stopPropagation();
  },

  handleNextClick(e) {
    const targetIndex =
      this.activeIndex < this.totalSlides ? this.activeIndex + 1 : 1;
    this.navigateToSlide(targetIndex);
    e.stopPropagation();
  },

  handleIndicatorClick(targetIndex) {
    if (targetIndex === this.activeIndex) return;
    this.navigateToSlide(targetIndex);
  },

  navigateToSlide(targetIndex) {
    // Validate targetIndex strictly
    if (
      !/^\d+$/.test(String(targetIndex)) ||
      targetIndex < 1 ||
      targetIndex > this.totalSlides
    ) {
      console.warn(`Invalid slide index: ${targetIndex}`);
      return;
    }

    const currentSlide = this.slides[this.activeIndex - 1];
    const targetSlide = this.slides[targetIndex - 1];

    if (!currentSlide || !targetSlide) {
      console.warn("Cannot navigate: missing slide elements");
      return;
    }

    const targetImage = targetSlide.querySelector("img");

    this.announceSlideChange(targetIndex);

    this.performSlideTransition(currentSlide, targetSlide, targetIndex);

    if (
      targetImage &&
      !targetImage.complete &&
      targetImage.naturalWidth === 0
    ) {
      this.showImageLoadingOverlay(targetImage, targetSlide);
    }

    const event = new CustomEvent("carousel:slide-changed", {
      bubbles: true,
      detail: {
        previousIndex: parseInt(this.activeIndex, 10),
        currentIndex: parseInt(targetIndex, 10),
        totalSlides: parseInt(this.totalSlides, 10),
      },
    });
    this.el.dispatchEvent(event);
  },

  announceSlideChange(targetIndex) {
    let liveRegion = document.getElementById(`${this.el.id}-live-region`);

    if (!liveRegion) {
      liveRegion = document.createElement("div");
      liveRegion.id = `${this.el.id}-live-region`;
      liveRegion.className = "sr-only";
      liveRegion.setAttribute("aria-live", "polite");
      liveRegion.setAttribute("aria-atomic", "true");
      this.el.appendChild(liveRegion);
    }

    liveRegion.textContent = `Slide ${targetIndex} of ${this.totalSlides}`;
  },

  performSlideTransition(currentSlide, targetSlide, targetIndex) {
    currentSlide.classList.add("transition-opacity", "duration-300");
    targetSlide.classList.add("transition-opacity", "duration-300");

    currentSlide.classList.remove(...this.classes.activeSlide.split(" "));
    currentSlide.classList.add(...this.classes.hiddenSlide.split(" "));
    currentSlide.setAttribute("aria-hidden", "true");

    targetSlide.classList.remove(...this.classes.hiddenSlide.split(" "));
    targetSlide.classList.add(...this.classes.activeSlide.split(" "));
    targetSlide.setAttribute("aria-hidden", "false");

    this.updateIndicators(targetIndex);

    this.activeIndex = targetIndex;

    if (this.shouldFocusSlide) {
      targetSlide.focus({ preventScroll: true });
    }
  },

  updateIndicators(targetIndex) {
    this.indicators?.forEach((indicator, index) => {
      const isActive = index + 1 === targetIndex;

      if (isActive) {
        indicator.classList.add(this.classes.activeIndicator);
        indicator.setAttribute("aria-current", "true");
      } else {
        indicator.classList.remove(this.classes.activeIndicator);
        indicator.setAttribute("aria-current", "false");
      }

      indicator.setAttribute("aria-label", `Go to slide ${index + 1}`);
    });
  },

  selectSlide(index) {
    this.handleIndicatorClick(index);
  },

  setupAutoplay() {
    if (this.shouldAutoplay) {
      this.startAutoplay();
    }
  },

  startAutoplay() {
    if (this.isHovered && this.el.dataset.pauseOnHover !== "false") return;
    if (this.isTouching) return;

    clearInterval(this.autoplayTimer);
    this.autoplayTimer = setInterval(() => {
      const nextIndex =
        this.activeIndex < this.totalSlides ? this.activeIndex + 1 : 1;
      this.navigateToSlide(nextIndex);
    }, this.autoplayInterval);
  },

  stopAutoplay() {
    clearInterval(this.autoplayTimer);
    this.autoplayTimer = null;
  },

  handleUserInteraction() {
    this.stopAutoplay();
    clearTimeout(this.userInteractionTimeout);
    this.userInteractionTimeout = setTimeout(() => {
      if (this.shouldAutoplay && !this.isHovered && !this.isTouching) {
        this.startAutoplay();
      }
    }, this.userInteractionDelay);
  },

  showInitialSlide() {
    this.slides.forEach((slide, index) => {
      const isActive = index + 1 === this.activeIndex;
      this.toggleSlideVisibility(slide, isActive);
      if (this.indicators[index]) {
        this.toggleIndicatorState(this.indicators[index], isActive);
      }
    });
  },

  toggleSlideVisibility(slide, isActive) {
    if (isActive) {
      slide.classList.add(...this.classes.activeSlide.split(" "));
      slide.classList.remove(...this.classes.hiddenSlide.split(" "));
      slide.setAttribute("aria-hidden", "false");
      slide.setAttribute("tabindex", "0");
    } else {
      slide.classList.remove(...this.classes.activeSlide.split(" "));
      slide.classList.add(...this.classes.hiddenSlide.split(" "));
      slide.setAttribute("aria-hidden", "true");
      slide.setAttribute("tabindex", "-1");
    }
  },

  toggleIndicatorState(indicator, isActive) {
    if (isActive) {
      indicator.classList.add(this.classes.activeIndicator);
      indicator.setAttribute("aria-current", "true");
    } else {
      indicator.classList.remove(this.classes.activeIndicator);
      indicator.setAttribute("aria-current", "false");
    }
  },

  setupImageLoadHandling() {
    this.imageLoaders.forEach((img) => {
      const overlay = this.createLoadingOverlay(img);
      if (!overlay) return;

      const slide = img.closest(".slide");
      if (slide) {
        slide.style.minHeight = "300px";
        overlay.style.minHeight = "300px";
      }

      img.parentNode.insertBefore(overlay, img.nextSibling);

      if (img.complete && img.naturalWidth > 0) {
        overlay.remove();
        if (slide) {
          slide.style.removeProperty("min-height");
        }
      } else {
        if (
          "loading" in HTMLImageElement.prototype &&
          !img.hasAttribute("loading")
        ) {
          img.loading = "lazy";
        }

        img.addEventListener(
          "load",
          () => {
            overlay.classList.add("fade-out");
            setTimeout(() => overlay.remove(), 300);
            if (slide) {
              slide.style.removeProperty("min-height");
            }
          },
          { once: true },
        );

        img.addEventListener(
          "error",
          () => {
            overlay.textContent = "";
            const errorDiv = document.createElement("div");
            errorDiv.className = "text-red-500 py-10";
            errorDiv.textContent = "Failed to load image";
            overlay.appendChild(errorDiv);
            overlay.classList.remove("animate-pulse");
          },
          { once: true },
        );
      }
    });
  },

  createLoadingOverlay(img) {
    if (!img) return null;

    const overlay = document.createElement("div");
    overlay.className =
      "absolute inset-0 bg-gray-200 dark:bg-gray-800 animate-pulse flex items-center justify-center transition-opacity duration-300";
    overlay.id = img.id + "-loading";

    const spinner = document.createElement("div");
    spinner.className =
      "animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary";
    overlay.appendChild(spinner);

    return overlay;
  },

  showImageLoadingOverlay(img, slide) {
    const existingOverlay = document.getElementById(img.id + "-loading");

    if (!existingOverlay && img) {
      const overlay = this.createLoadingOverlay(img);
      if (overlay) {
        slide.appendChild(overlay);

        img.addEventListener(
          "load",
          () => {
            overlay.classList.add("fade-out");
            setTimeout(() => overlay.remove(), 300);
          },
          { once: true },
        );
      }
    }
  },

  // Helper method: sanitizes a number input
  sanitizeNumber(value) {
    const num = parseInt(value, 10);
    return !isNaN(num) ? num : 0;
  },

  // Helper method: sanitizes class names by allowing only alphanumeric, dash, underscore, and space
  sanitizeClassName(classString) {
    if (!classString || typeof classString !== "string") return null;
    return classString
      .split(" ")
      .map((name) => name.replace(/[^a-zA-Z0-9_\-]/g, ""))
      .filter((name) => name.length > 0)
      .join(" ");
  },
};

export default Carousel;

/**
 * ScrollArea Hook for Phoenix LiveView — custom scrollbar engine (Base UI parity).
 *
 * Hides the native scrollbar and drives a custom `[data-part="thumb"]` inside a
 * `[data-part="scrollbar"]`: the thumb is sized PROPORTIONALLY to the content (exposed as the
 * `--scroll-area-thumb-height/width` CSS vars), positioned by transform as the viewport scrolls, and
 * draggable. A scrollbar is hidden when its axis doesn't overflow.
 *
 * Mirrors Base UI's state on the root + viewport + scrollbar(s) + content:
 *   data-scrolling                       — set briefly while scrolling
 *   data-hovering   (scrollbar)          — while the pointer is over the root
 *   data-has-overflow-x / -y             — when that axis overflows
 *   data-overflow-{x,y}-{start,end}      — when scrolled away from that edge
 * and exposes the distance from each edge as `--scroll-area-overflow-{x,y}-{start,end}` (px) so a
 * consumer can fade the edges (the Base UI "scroll fade" demo).
 *
 * Element lookup prefers `data-part` (headless); it falls back to the styled component's class names
 * (`.scroll-viewport`, `.thumb-y/x`, `.scrollbar-y/x`) so the existing styled scroll area keeps working.
 */

let ScrollArea = {
  mounted() {
    const { el } = this;
    this.viewport = q(el, '[data-part="viewport"]', ".scroll-viewport");
    this.content = this.viewport && this.viewport.querySelector('[data-part="content"]');
    this.scrollbarY = q(el, '[data-part="scrollbar"][data-orientation="vertical"]', ".scrollbar-y");
    this.scrollbarX = q(el, '[data-part="scrollbar"][data-orientation="horizontal"]', ".scrollbar-x");
    this.thumbY = (this.scrollbarY && this.scrollbarY.querySelector('[data-part="thumb"]')) || el.querySelector(".thumb-y");
    this.thumbX = (this.scrollbarX && this.scrollbarX.querySelector('[data-part="thumb"]')) || el.querySelector(".thumb-x");

    if (!this.viewport) {
      if (this.scrollbarY) this.scrollbarY.style.display = "none";
      if (this.scrollbarX) this.scrollbarX.style.display = "none";
      return;
    }

    this.boundUpdate = () => this.updateThumb();
    this.boundScroll = () => {
      this.markScrolling();
      this.updateThumb();
    };
    this.viewport.addEventListener("scroll", this.boundScroll, { passive: true });
    window.addEventListener("resize", this.boundUpdate);

    // hover state for auto-hiding scrollbars
    this.boundEnter = () => this.setHovering(true);
    this.boundLeave = () => this.setHovering(false);
    el.addEventListener("pointerenter", this.boundEnter);
    el.addEventListener("pointerleave", this.boundLeave);

    if (this.thumbY) {
      this.onThumbYPointerDownBound = (e) => this.onThumbYPointerDown(e);
      this.thumbY.addEventListener("pointerdown", this.onThumbYPointerDownBound);
    }
    if (this.thumbX) {
      this.onThumbXPointerDownBound = (e) => this.onThumbXPointerDown(e);
      this.thumbX.addEventListener("pointerdown", this.onThumbXPointerDownBound);
    }

    this.resizeObserver = new ResizeObserver(() => this.updateThumb());
    this.resizeObserver.observe(this.viewport);
    if (this.content) this.resizeObserver.observe(this.content);

    this.updateThumb();
  },

  updateAxis({ contentSize, clientSize, scrollPos, thumb, scrollbar, axis }) {
    const has = contentSize > clientSize + 1;
    if (!has) {
      if (scrollbar) scrollbar.style.display = "none";
      return;
    }
    if (scrollbar) scrollbar.style.display = "";
    if (thumb && scrollbar) {
      // PROPORTIONAL thumb size (Base UI): track * (viewport / content), min 20px. Exposed as a CSS
      // var so the consumer's thumb opts in with `height/width: var(--scroll-area-thumb-*)`.
      const trackSize = axis === "vertical" ? scrollbar.clientHeight : scrollbar.clientWidth;
      const thumbSize = Math.max(20, (clientSize / contentSize) * trackSize);
      this.el.style.setProperty(
        axis === "vertical" ? "--scroll-area-thumb-height" : "--scroll-area-thumb-width",
        `${thumbSize}px`,
      );
      const actual = (axis === "vertical" ? thumb.offsetHeight : thumb.offsetWidth) || thumbSize;
      const maxScroll = contentSize - clientSize;
      const maxThumb = trackSize - actual;
      const pos = maxScroll > 0 ? (scrollPos / maxScroll) * maxThumb : 0;
      thumb.style.transform = axis === "vertical" ? `translateY(${pos}px)` : `translateX(${pos}px)`;
    }
  },

  updateThumb() {
    if (!this.viewport) return;
    const v = this.viewport;

    const hasY = v.scrollHeight > v.clientHeight + 1;
    const hasX = v.scrollWidth > v.clientWidth + 1;

    this.updateAxis({ contentSize: v.scrollHeight, clientSize: v.clientHeight, scrollPos: v.scrollTop, thumb: this.thumbY, scrollbar: this.scrollbarY, axis: "vertical" });
    this.updateAxis({ contentSize: v.scrollWidth, clientSize: v.clientWidth, scrollPos: v.scrollLeft, thumb: this.thumbX, scrollbar: this.scrollbarX, axis: "horizontal" });

    // overflow presence
    this.flag("data-has-overflow-y", hasY, [this.el, this.viewport, this.scrollbarY, this.scrollbarX, this.content]);
    this.flag("data-has-overflow-x", hasX, [this.el, this.viewport, this.scrollbarX, this.scrollbarY, this.content]);

    // per-edge overflow distance (for the scroll-fade mask) + data flags
    const yStart = v.scrollTop;
    const yEnd = v.scrollHeight - v.clientHeight - v.scrollTop;
    const xStart = v.scrollLeft;
    const xEnd = v.scrollWidth - v.clientWidth - v.scrollLeft;
    const set = (name, px) => this.el.style.setProperty(name, `${Math.max(0, Math.round(px))}px`);
    set("--scroll-area-overflow-y-start", hasY ? yStart : 0);
    set("--scroll-area-overflow-y-end", hasY ? yEnd : 0);
    set("--scroll-area-overflow-x-start", hasX ? xStart : 0);
    set("--scroll-area-overflow-x-end", hasX ? xEnd : 0);
    this.flag("data-overflow-y-start", hasY && yStart > 0, [this.el, this.viewport, this.content]);
    this.flag("data-overflow-y-end", hasY && yEnd > 1, [this.el, this.viewport, this.content]);
    this.flag("data-overflow-x-start", hasX && xStart > 0, [this.el, this.viewport, this.content]);
    this.flag("data-overflow-x-end", hasX && xEnd > 1, [this.el, this.viewport, this.content]);
  },

  flag(attr, on, nodes) {
    nodes.forEach((n) => n && n.toggleAttribute(attr, on));
  },

  setHovering(on) {
    [this.scrollbarY, this.scrollbarX].forEach((s) => s && s.toggleAttribute("data-hovering", on));
  },

  markScrolling() {
    this.flag("data-scrolling", true, [this.el, this.viewport, this.scrollbarY, this.scrollbarX, this.content]);
    clearTimeout(this._scrollTimer);
    this._scrollTimer = setTimeout(
      () => this.flag("data-scrolling", false, [this.el, this.viewport, this.scrollbarY, this.scrollbarX, this.content]),
      500,
    );
  },

  // ---- thumb dragging (unchanged logic; thumb size read from offset*) --------

  onThumbYPointerDown(e) {
    e.preventDefault();
    this.isDraggingY = true;
    this.startY = e.clientY;
    this.startScrollTop = this.viewport.scrollTop;
    this.boundThumbYPointerMove = (ev) => this.onThumbYPointerMove(ev);
    this.boundThumbYPointerUp = () => this.onThumbYPointerUp();
    document.addEventListener("pointermove", this.boundThumbYPointerMove);
    document.addEventListener("pointerup", this.boundThumbYPointerUp);
  },

  onThumbYPointerMove(e) {
    e.preventDefault();
    const dy = e.clientY - this.startY;
    const { scrollHeight, clientHeight } = this.viewport;
    const thumbHeight = (this.thumbY && this.thumbY.offsetHeight) || 20;
    const maxScroll = scrollHeight - clientHeight;
    const maxThumb = clientHeight - thumbHeight;
    this.viewport.scrollTop = Math.max(0, Math.min(this.startScrollTop + dy * (maxScroll / maxThumb), maxScroll));
  },

  onThumbYPointerUp() {
    this.isDraggingY = false;
    document.removeEventListener("pointermove", this.boundThumbYPointerMove);
    document.removeEventListener("pointerup", this.boundThumbYPointerUp);
  },

  onThumbXPointerDown(e) {
    e.preventDefault();
    this.isDraggingX = true;
    this.startX = e.clientX;
    this.startScrollLeft = this.viewport.scrollLeft;
    this.boundThumbXPointerMove = (ev) => this.onThumbXPointerMove(ev);
    this.boundThumbXPointerUp = () => this.onThumbXPointerUp();
    document.addEventListener("pointermove", this.boundThumbXPointerMove);
    document.addEventListener("pointerup", this.boundThumbXPointerUp);
  },

  onThumbXPointerMove(e) {
    e.preventDefault();
    const dx = e.clientX - this.startX;
    const { scrollWidth, clientWidth } = this.viewport;
    const thumbWidth = (this.thumbX && this.thumbX.offsetWidth) || 20;
    const maxScroll = scrollWidth - clientWidth;
    const maxThumb = clientWidth - thumbWidth;
    this.viewport.scrollLeft = Math.max(0, Math.min(this.startScrollLeft + dx * (maxScroll / maxThumb), maxScroll));
  },

  onThumbXPointerUp() {
    this.isDraggingX = false;
    document.removeEventListener("pointermove", this.boundThumbXPointerMove);
    document.removeEventListener("pointerup", this.boundThumbXPointerUp);
  },

  destroyed() {
    this.viewport?.removeEventListener("scroll", this.boundScroll);
    window.removeEventListener("resize", this.boundUpdate);
    this.el.removeEventListener("pointerenter", this.boundEnter);
    this.el.removeEventListener("pointerleave", this.boundLeave);
    this.thumbY?.removeEventListener("pointerdown", this.onThumbYPointerDownBound);
    this.thumbX?.removeEventListener("pointerdown", this.onThumbXPointerDownBound);
    this.resizeObserver?.disconnect();
    clearTimeout(this._scrollTimer);
  },
};

function q(el, primary, fallback) {
  return el.querySelector(primary) || el.querySelector(fallback);
}

export default ScrollArea;

const Sidebar = {
  defaults: {
    expandedWidth: "250px",
    collapsedWidth: "60px",
    transitionDuration: "0.3s",
    labelAnimationDelay: 10,
  },

  getElements(el) {
    const sidebarSelector = el.getAttribute("data-sidebar-selector");
    if (!sidebarSelector) return null;

    if (!this.isValidSelector(sidebarSelector)) return null;

    const sidebar = document.querySelector(sidebarSelector);
    if (!sidebar) return null;

    return {
      sidebar,
      labels: sidebar.querySelectorAll("[data-item-label]"),
    };
  },

  isValidSelector(selector) {
    try {
      document.querySelector(selector);
      return true;
    } catch (e) {
      console.error("Invalid selector:", selector);
      return false;
    }
  },

  getConfig(sidebar) {
    const expandedWidth = sidebar.getAttribute("data-expanded-width");
    const collapsedWidth = sidebar.getAttribute("data-collapsed-width");

    return {
      expandedWidth:
        this.sanitizeCssValue(expandedWidth) || this.defaults.expandedWidth,
      collapsedWidth:
        this.sanitizeCssValue(collapsedWidth) || this.defaults.collapsedWidth,
      isMinimized: sidebar.getAttribute("data-minimized") === "true",
    };
  },

  sanitizeCssValue(value) {
    if (!value) return null;

    const validPattern = /^[0-9]+(px|em|rem|%|vh|vw)$/;
    return validPattern.test(value) ? value : null;
  },

  expandSidebar(sidebar, labels, expandedWidth) {
    sidebar.style.width = expandedWidth;
    sidebar.setAttribute("data-minimized", "false");

    this.animateLabels(labels, true);
  },

  collapseSidebar(sidebar, labels, collapsedWidth) {
    sidebar.style.width = collapsedWidth;
    sidebar.setAttribute("data-minimized", "true");

    this.hideLabels(labels);
  },

  animateLabels(labels, show) {
    if (show) {
      labels.forEach((label) => {
        label.classList.remove("hidden");
        label.classList.add("opacity-0");

        setTimeout(() => {
          label.classList.add(
            "transition-opacity",
            "duration-200",
            "opacity-100",
          );
          label.classList.remove("opacity-0");
        }, this.defaults.labelAnimationDelay);
      });
    }
  },

  hideLabels(labels) {
    labels.forEach((label) => {
      label.classList.add("hidden");
      label.classList.remove(
        "opacity-100",
        "transition-opacity",
        "duration-200",
      );
    });
  },

  Sidebar(elements, config) {
    const { sidebar, labels } = elements;
    const { expandedWidth, collapsedWidth, isMinimized } = config;

    sidebar.style.transition = `width ${this.defaults.transitionDuration} ease`;

    if (isMinimized) {
      this.expandSidebar(sidebar, labels, expandedWidth);
    } else {
      this.collapseSidebar(sidebar, labels, collapsedWidth);
    }
  },

  mounted() {
    this.clickHandler = this.handleClick.bind(this);
    this.el.addEventListener("click", this.clickHandler);
  },

  handleClick() {
    const elements = this.getElements(this.el);
    if (!elements) return;

    const config = this.getConfig(elements.sidebar);
    this.Sidebar(elements, config);

    const icon = this.el.querySelector(".minimize-icon");
    if (icon) {
      icon.classList.toggle("rotate-180");
    }
  },

  destroy() {
    if (this.el && this.clickHandler) {
      this.el.removeEventListener("click", this.clickHandler);
      this.clickHandler = null;
    }
  },
};

export default Sidebar;

