/* 10% */
[data-opacity="transparent"] {
    --overlay-opacity: calc(var(--opacity-base) * 1%);
}
/* 20% */
[data-opacity="translucent"] {
    --overlay-opacity: calc(var(--opacity-base) * 2%);
}
/* 30% */
[data-opacity="semi_transparent"] {
    --overlay-opacity: calc(var(--opacity-base) * 3%);
}
/* 40% */
[data-opacity="lightly_tinted"] {
    --overlay-opacity: calc(var(--opacity-base) * 4%);
}
/* 50% */
[data-opacity="tinted"] {
    --overlay-opacity: calc(var(--opacity-base) * 5%);
}
/* 60% */
[data-opacity="semi_opaque"] {
    --overlay-opacity: calc(var(--opacity-base) * 6%);
}
/* 70% */
[data-opacity="opaque"] {
    --overlay-opacity: calc(var(--opacity-base) * 7%);
}
/* 80% */
[data-opacity="heavily_tinted"] {
    --overlay-opacity: calc(var(--opacity-base) * 8%);
}
/* 90% */
[data-opacity="almost_solid"] {
    --overlay-opacity: calc(var(--opacity-base) * 9%);
}
/* 100% */
[data-opacity="solid"] {
    --overlay-opacity: calc(var(--opacity-base) * 10%);
}


